INSERT INTO `marcas` VALUES (1,'BOHN','BOHN','Bohn ofrece equipos de refrigeración comercial e industrial, como condensadores, evaporadores, unidades condensadoras, racks, serpentines, fábricas de hielo y soluciones para transporte refrigerado, compatibles con refrigerantes sintéticos y naturales como CO₂ y NH₃.',1,'2026-06-05 16:06:03','2026-06-12 23:38:59',NULL,3,3,NULL),(2,'TRANE','TRANE','Trane ofrece equipos de aire acondicionado como sistemas centrales, mini split, unidades paquete y equipos de gran capacidad, además de controles y soluciones para edificios, utilizados en aplicaciones residenciales y comerciales.',1,'2026-06-12 23:36:56',NULL,NULL,3,NULL,NULL),(3,'COPELAND','COPELAND','Copeland ofrece compresores herméticos y semiherméticos, así como controles y componentes electrónicos para sistemas de refrigeración, aire acondicionado y calefacción, utilizados en aplicaciones comerciales, industriales y residenciales.',1,'2026-06-12 23:37:21',NULL,NULL,3,NULL,NULL),(4,'FULL-GAUGE','FULL GAUGE','Full Gauge ofrece controladores electrónicos, termostatos digitales, sensores, temporizadores y registradores, utilizados en cámaras de refrigeración y congelación, vitrinas, racks y equipos de aire acondicionado, con opciones de alarmas y monitoreo.',1,'2026-06-12 23:37:50',NULL,NULL,3,NULL,NULL),(5,'CARRIER','Carrier','Carrier es una marca dedicada a ofrecer equipos de aire acondicionado para uso residencial, comercial e industrial, además de sistemas VRF, chillers, manejadoras. Permiten un funcionamiento estable y el control básico de la temperatura.',1,'2026-06-12 23:38:13',NULL,NULL,3,NULL,NULL),(6,'JOHNSON','Johnson Controls','Johnson Controls ofrece equipos y soluciones para climatización, refrigeración y control de edificios, incluyendo chillers, manejadoras de aire, sistemas VRF, controles y automatización para aplicaciones comerciales e industriales.',1,'2026-06-12 23:38:45',NULL,NULL,3,NULL,NULL),(7,'ADESA','adesa','Adesa ofrece limpiadores y químicos para sistemas de refrigeración y aire acondicionado, como limpiadores de serpentines, desengrasantes y productos para mantenimiento de equipos, utilizados en servicios preventivos y correctivos.',1,'2026-06-12 23:39:19',NULL,NULL,3,NULL,NULL),(8,'EMBRACO','embraco','Embraco ofrece compresores herméticos para refrigeración doméstica y comercial, incluyendo modelos alternativos e inverter, utilizados en refrigeradores, congeladores y equipos comerciales de pequeña y mediana capacidad.',1,'2026-06-12 23:39:44',NULL,NULL,3,NULL,NULL),(9,'ACEMIRE','acemire','Acemire ofrece lubricantes para sistemas de refrigeración y aire acondicionado, incluyendo alquilbencenos, polialfaolefinas, poliolésteres, polialquilenglicoles y poliviniléteres, utilizados en compresores herméticos y semiherméticos.',1,'2026-06-12 23:40:04',NULL,NULL,3,NULL,NULL),(10,'SPORLAN','SPORLAN','Sporlan es una marca de componentes para refrigeración y aire acondicionado. Ofrece válvulas de expansión termostáticas y electrónicas, válvulas solenoides, filtros secadores, reguladores de presión y piezas de control, utilizados en sistemas HVAC/R residenciales, comerciales, industriales y de transporte para gestionar el flujo de refrigerante y proteger los circuitos.',1,'2026-06-12 23:40:36',NULL,NULL,3,NULL,NULL),(11,'MIDEA','Midea','Reconocida por su excelente relación calidad-precio, tecnología moderna y compromiso con la eficiencia energética. Midea es el fabricante número uno de aires acondicionados en el mundo. Su fabricación de aires de última generación mantienen tu casa fresca y cómoda durante todo el año. Encontrarás una amplia variedad de opciones para mantener fresco tu hogar, desde ventiladores hasta aires acondicionados de ventana, portátiles, minisplits.',1,'2026-06-12 23:41:28',NULL,NULL,3,NULL,NULL),(12,'DANFOSS','Danfoss',NULL,1,'2026-06-12 23:42:10',NULL,NULL,3,NULL,NULL),(13,'SOLER-PALAU','Soler & Palau',NULL,1,'2026-06-12 23:43:33',NULL,NULL,3,NULL,NULL),(14,'BITZER','Bitzer',NULL,1,'2026-06-12 23:44:57',NULL,NULL,3,NULL,NULL),(15,'IMBERA','Imbera',NULL,1,'2026-06-12 23:45:49',NULL,NULL,3,NULL,NULL),(16,'KEEL','KEEL',NULL,1,'2026-06-23 14:38:02',NULL,NULL,3,NULL,NULL),(17,'IGAS','iGas',NULL,1,'2026-06-23 22:20:58',NULL,NULL,3,NULL,NULL);
