--
-- Table structure for table `producto_documentos`
--

DROP TABLE IF EXISTS `producto_documentos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `producto_documentos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `producto_id` bigint(20) unsigned NOT NULL,
  `tipo_documento` enum('FOTO_PRINCIPAL','FICHA_TECNICA','MANUAL','CERTIFICADO','OTRO') NOT NULL DEFAULT 'OTRO',
  `titulo` varchar(160) NOT NULL,
  `descripcion` varchar(255) DEFAULT NULL,
  `archivo_path` varchar(255) NOT NULL,
  `nombre_original` varchar(255) NOT NULL,
  `mime_type` varchar(120) NOT NULL,
  `extension` varchar(20) NOT NULL,
  `size_bytes` bigint(20) unsigned NOT NULL DEFAULT 0,
  `es_principal` tinyint(1) NOT NULL DEFAULT 0,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_producto_documentos_producto_id` (`producto_id`),
  KEY `idx_producto_documentos_tipo_documento` (`tipo_documento`),
  KEY `idx_producto_documentos_activo` (`activo`),
  KEY `idx_producto_documentos_deleted_at` (`deleted_at`),
  KEY `idx_producto_documentos_principal` (`producto_id`,`tipo_documento`,`es_principal`),
  KEY `fk_producto_documentos_created_by` (`created_by`),
  KEY `fk_producto_documentos_updated_by` (`updated_by`),
  KEY `fk_producto_documentos_deleted_by` (`deleted_by`),
  CONSTRAINT `fk_producto_documentos_created_by` FOREIGN KEY (`created_by`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_producto_documentos_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_producto_documentos_producto` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`),
  CONSTRAINT `fk_producto_documentos_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
