DROP TABLE IF EXISTS `productos_kit_componentes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `productos_kit_componentes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `producto_kit_id` bigint(20) unsigned NOT NULL,
  `producto_componente_id` bigint(20) unsigned NOT NULL,
  `cantidad` decimal(18,6) NOT NULL,
  `merma_porcentaje` decimal(9,6) NOT NULL DEFAULT 0.000000,
  `orden` int(10) unsigned NOT NULL DEFAULT 1,
  `observaciones` text DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_productos_kit_componentes_relacion` (`producto_kit_id`,`producto_componente_id`,`deleted_at`),
  KEY `idx_productos_kit_componentes_kit` (`producto_kit_id`),
  KEY `idx_productos_kit_componentes_componente` (`producto_componente_id`),
  KEY `idx_productos_kit_componentes_activo` (`activo`),
  KEY `idx_productos_kit_componentes_deleted_at` (`deleted_at`),
  KEY `fk_productos_kit_componentes_created_by` (`created_by`),
  KEY `fk_productos_kit_componentes_updated_by` (`updated_by`),
  KEY `fk_productos_kit_componentes_deleted_by` (`deleted_by`),
  CONSTRAINT `fk_productos_kit_componentes_componente` FOREIGN KEY (`producto_componente_id`) REFERENCES `productos` (`id`),
  CONSTRAINT `fk_productos_kit_componentes_created_by` FOREIGN KEY (`created_by`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_productos_kit_componentes_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_productos_kit_componentes_kit` FOREIGN KEY (`producto_kit_id`) REFERENCES `productos` (`id`),
  CONSTRAINT `fk_productos_kit_componentes_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
