DROP TABLE IF EXISTS `ticket_alta_producto_movimientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ticket_alta_producto_movimientos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint(20) unsigned NOT NULL,
  `accion` varchar(50) NOT NULL,
  `estatus_anterior` varchar(30) DEFAULT NULL,
  `estatus_nuevo` varchar(30) DEFAULT NULL,
  `comentario` text DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ticket_movimientos_ticket` (`ticket_id`),
  KEY `idx_ticket_movimientos_accion` (`accion`),
  KEY `idx_ticket_movimientos_created_at` (`created_at`),
  KEY `fk_ticket_movimientos_user` (`user_id`),
  CONSTRAINT `fk_ticket_movimientos_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `ticket_alta_productos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ticket_movimientos_user` FOREIGN KEY (`user_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=208 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
