DROP TABLE IF EXISTS `ticket_alta_producto_partidas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ticket_alta_producto_partidas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint(20) unsigned NOT NULL,
  `orden` int(10) unsigned NOT NULL DEFAULT 1,
  `modelo` varchar(120) NOT NULL,
  `descripcion` varchar(255) NOT NULL,
  `marca_texto` varchar(160) NOT NULL,
  `unidad_sat_id` bigint(20) unsigned DEFAULT NULL,
  `clave_sat_id` bigint(20) unsigned DEFAULT NULL,
  `moneda_id` bigint(20) unsigned NOT NULL,
  `proveedor_id` bigint(20) unsigned DEFAULT NULL,
  `proveedor_texto` varchar(255) DEFAULT NULL,
  `costo` decimal(18,6) NOT NULL DEFAULT 0.000000,
  `lleva_serie` tinyint(1) NOT NULL DEFAULT 0,
  `peso` decimal(18,4) DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `clave_autorizada` varchar(16) DEFAULT NULL,
  `descripcion_autorizada` varchar(255) DEFAULT NULL,
  `unidad_sat_autorizada_id` bigint(20) unsigned DEFAULT NULL,
  `clave_sat_autorizada_id` bigint(20) unsigned DEFAULT NULL,
  `sat_pendiente` tinyint(1) NOT NULL DEFAULT 0,
  `respuesta_revision` text DEFAULT NULL,
  `aprobado_at` timestamp NULL DEFAULT NULL,
  `aprobado_by` bigint(20) unsigned DEFAULT NULL,
  `producto_existente_id` bigint(20) unsigned DEFAULT NULL,
  `validacion_estado` varchar(30) NOT NULL DEFAULT 'OK',
  `validacion_mensaje` varchar(255) DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ticket_partidas_ticket` (`ticket_id`),
  KEY `idx_ticket_partidas_modelo` (`modelo`),
  KEY `idx_ticket_partidas_estado` (`validacion_estado`),
  KEY `idx_ticket_partidas_clave_autorizada` (`clave_autorizada`),
  KEY `idx_ticket_partidas_unidad_sat_autorizada` (`unidad_sat_autorizada_id`),
  KEY `idx_ticket_partidas_clave_sat_autorizada` (`clave_sat_autorizada_id`),
  KEY `idx_ticket_partidas_sat_pendiente` (`sat_pendiente`),
  KEY `idx_ticket_tap_ticket_deleted_orden_id` (`ticket_id`,`deleted_at`,`orden`,`id`),
