--
-- Table structure for table `ticket_alta_productos`
--

DROP TABLE IF EXISTS `ticket_alta_productos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ticket_alta_productos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `folio` varchar(30) NOT NULL,
  `folio_numero` bigint(20) unsigned NOT NULL,
  `empresa_id` bigint(20) unsigned NOT NULL,
  `almacen_id` bigint(20) unsigned NOT NULL,
  `consecutivo` int(10) unsigned NOT NULL,
  `estatus` enum('EN_REVISION','APROBADO','RECHAZADO','CANCELADO') NOT NULL DEFAULT 'EN_REVISION',
  `solicitante_usuario_id` bigint(20) unsigned DEFAULT NULL,
  `solicitante_nombre` varchar(160) NOT NULL,
  `solicitante_email` varchar(190) NOT NULL,
  `observaciones_generales` text DEFAULT NULL,
  `archivo_adjunto_nombre` varchar(255) DEFAULT NULL,
  `archivo_adjunto_path` varchar(500) DEFAULT NULL,
  `archivo_adjunto_mime` varchar(120) DEFAULT NULL,
  `archivo_adjunto_size` bigint(20) unsigned DEFAULT NULL,
  `revisor_id` bigint(20) unsigned DEFAULT NULL,
  `fecha_revision` datetime DEFAULT NULL,
  `motivo_rechazo` varchar(255) DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ticket_alta_productos_folio` (`folio`),
  UNIQUE KEY `uk_ticket_alta_productos_almacen_consecutivo` (`almacen_id`,`consecutivo`),
  KEY `idx_ticket_alta_productos_folio_numero` (`folio_numero`),
  KEY `idx_ticket_alta_productos_empresa_id` (`empresa_id`),
  KEY `idx_ticket_alta_productos_almacen_id` (`almacen_id`),
  KEY `idx_ticket_alta_productos_consecutivo` (`consecutivo`),
  KEY `idx_ticket_alta_productos_estatus` (`estatus`),
  KEY `idx_tickets_estatus_deleted_created_almacen` (`estatus`,`deleted_at`,`created_at`,`almacen_id`),
  KEY `idx_ticket_alta_productos_activo` (`activo`),
  KEY `idx_ticket_alta_productos_deleted_at` (`deleted_at`),
  KEY `fk_ticket_alta_productos_solicitante_usuario` (`solicitante_usuario_id`),
  KEY `fk_ticket_alta_productos_revisor` (`revisor_id`),
  KEY `fk_ticket_alta_productos_created_by` (`created_by`),
  KEY `fk_ticket_alta_productos_updated_by` (`updated_by`),
  KEY `fk_ticket_alta_productos_deleted_by` (`deleted_by`),
  CONSTRAINT `fk_ticket_alta_productos_almacen` FOREIGN KEY (`almacen_id`) REFERENCES `almacenes` (`id`),
  CONSTRAINT `fk_ticket_alta_productos_created_by` FOREIGN KEY (`created_by`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_ticket_alta_productos_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_ticket_alta_productos_empresa` FOREIGN KEY (`empresa_id`) REFERENCES `empresas` (`id`),
  CONSTRAINT `fk_ticket_alta_productos_revisor` FOREIGN KEY (`revisor_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_ticket_alta_productos_solicitante_usuario` FOREIGN KEY (`solicitante_usuario_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_ticket_alta_productos_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ticket_alta_productos`
--

