--
-- Table structure for table `usuarios`
--

DROP TABLE IF EXISTS `usuarios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `usuarios` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `empresa_id` bigint(20) unsigned DEFAULT NULL,
  `almacen_id` bigint(20) unsigned DEFAULT NULL,
  `nombre` varchar(60) NOT NULL,
  `nombre_2` varchar(30) DEFAULT NULL,
  `apellido_paterno` varchar(60) NOT NULL,
  `apellido_materno` varchar(60) DEFAULT NULL,
  `genero` enum('M','F','O') DEFAULT NULL,
  `username` varchar(30) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `motivo_inactivacion` text DEFAULT NULL,
  `fecha_inactivacion` datetime DEFAULT NULL,
  `inactivado_por` bigint(20) unsigned DEFAULT NULL,
  `puesto` varchar(120) DEFAULT NULL,
  `email` varchar(160) NOT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `telefono_movil` varchar(20) DEFAULT NULL,
  `foto` varchar(255) DEFAULT NULL,
  `ui_tema_id` bigint(20) unsigned DEFAULT NULL,
  `ultimo_login_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `eliminado_en` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_usuarios_username` (`username`),
  UNIQUE KEY `uk_usuarios_email` (`email`),
  KEY `fk_usuarios_inactivado_por` (`inactivado_por`),
  KEY `fk_usuarios_created_by` (`created_by`),
  KEY `fk_usuarios_updated_by` (`updated_by`),
  KEY `fk_usuarios_deleted_by` (`deleted_by`),
  KEY `idx_usuarios_empresa_id` (`empresa_id`),
  KEY `idx_usuarios_almacen_id` (`almacen_id`),
  KEY `idx_usuarios_ui_tema_id` (`ui_tema_id`),
  KEY `idx_usuarios_activo` (`activo`),
  KEY `idx_usuarios_deleted_at` (`deleted_at`),
  KEY `idx_usuarios_eliminado_en` (`eliminado_en`),
  CONSTRAINT `fk_usuarios_almacen` FOREIGN KEY (`almacen_id`) REFERENCES `almacenes` (`id`),
  CONSTRAINT `fk_usuarios_created_by` FOREIGN KEY (`created_by`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_usuarios_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_usuarios_empresa` FOREIGN KEY (`empresa_id`) REFERENCES `empresas` (`id`),
  CONSTRAINT `fk_usuarios_inactivado_por` FOREIGN KEY (`inactivado_por`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_usuarios_ui_tema` FOREIGN KEY (`ui_tema_id`) REFERENCES `ui_temas` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_usuarios_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

